import crypto from 'node:crypto'
import fs from 'node:fs'
import { betterAuth } from 'better-auth'
import { drizzleAdapter } from 'better-auth/adapters/drizzle'
import { admin, username } from 'better-auth/plugins'
import { tanstackStartCookies } from 'better-auth/tanstack-start'
import { and, eq } from 'drizzle-orm'

import { db } from '#/db'
import { account, user } from '#/db/schema'
import { config } from '#/lib/config'

// BETTER_AUTH_SECRET wins; otherwise generate one on first boot and keep it in the data dir.
function loadSecret() {
  if (process.env.BETTER_AUTH_SECRET) return process.env.BETTER_AUTH_SECRET
  if (!fs.existsSync(config.secretPath)) {
    fs.writeFileSync(
      config.secretPath,
      crypto.randomBytes(32).toString('hex'),
      {
        mode: 0o600,
      },
    )
  }
  return fs.readFileSync(config.secretPath, 'utf8').trim()
}

export const auth = betterAuth({
  database: drizzleAdapter(db, { provider: 'sqlite' }),
  secret: loadSecret(),
  // With BOOKSERVE_URL unset, the base URL (and trusted origin) is taken from each request,
  // honoring X-Forwarded-Host/Proto from a reverse proxy. Cookies are then not marked Secure,
  // so plain-http LAN access works; setting an https BOOKSERVE_URL turns Secure cookies on.
  baseURL: config.publicUrl,
  advanced: {
    trustedProxyHeaders: true,
    ...(config.publicUrl ? {} : { useSecureCookies: false }),
  },
  emailAndPassword: {
    enabled: true,
    disableSignUp: true,
  },
  // Role changes and deletes go through the server functions in src/lib/user-functions.ts,
  // which refuse self-demotion/self-deletion and removing the last admin. Close the raw
  // HTTP endpoints that could bypass those guards (auth.api calls are unaffected).
  disabledPaths: [
    '/admin/set-role',
    '/admin/update-user',
    '/admin/remove-user',
  ],
  plugins: [username(), admin(), tanstackStartCookies()],
})

const sha256 = (value: string) =>
  crypto.createHash('sha256').update(value).digest('hex')

// Per username: the password (as sha256) last verified and the account's
// password hash it matched. Hashing is slow on a Pi and OPDS readers send
// Basic credentials with every feed page and cover, so a password is checked
// once per password hash; a password change forces a new check.
const verifiedBasic = new Map<string, { password: string; hash: string }>()

// Per username: unsuccessful Basic attempts in the current window. Better Auth's
// sign-in rate limit doesn't cover this path, so guessing is throttled here.
// A reader whose password is already verified isn't locked out by it.
const basicAttempts = new Map<string, { count: number; until: number }>()
const MAX_ATTEMPTS = 5
const ATTEMPT_WINDOW_MS = 60_000

function recordAttempt(name: string) {
  const now = Date.now()
  for (const [key, entry] of basicAttempts) {
    if (entry.until <= now) basicAttempts.delete(key)
  }
  const entry = basicAttempts.get(name)
  if (entry) entry.count++
  else basicAttempts.set(name, { count: 1, until: now + ATTEMPT_WINDOW_MS })
}

// The signed-in user for a request: a session cookie, or HTTP Basic
// credentials (username and password) from clients such as OPDS readers.
export async function requestUser(request: Request) {
  const session = await auth.api.getSession({ headers: request.headers })
  if (session) return session.user
  const match = /^Basic\s+(\S+)$/i.exec(
    request.headers.get('authorization') ?? '',
  )
  if (!match) return null
  const decoded = Buffer.from(match[1], 'base64').toString('utf8')
  const sep = decoded.indexOf(':')
  if (sep < 0) return null
  const name = decoded.slice(0, sep).toLowerCase()
  const password = decoded.slice(sep + 1)
  const row = db
    .select({ user, hash: account.password })
    .from(user)
    .innerJoin(
      account,
      and(eq(account.userId, user.id), eq(account.providerId, 'credential')),
    )
    .where(eq(user.username, name))
    .get()
  const banned =
    row?.user.banned &&
    (!row.user.banExpires || row.user.banExpires > new Date())
  if (banned) return null

  const cached = verifiedBasic.get(name)
  if (
    row?.hash &&
    cached?.hash === row.hash &&
    cached.password === sha256(password)
  ) {
    return row.user
  }
  const attempts = basicAttempts.get(name)
  if (
    attempts &&
    attempts.count >= MAX_ATTEMPTS &&
    attempts.until > Date.now()
  ) {
    return null
  }
  // Count the attempt before hashing, so parallel guesses can't all slip in
  // under the limit; a correct password clears the count.
  recordAttempt(name)
  const ctx = await auth.$context
  if (!row?.hash) {
    // Hash anyway, so the response time doesn't reveal which usernames exist.
    await ctx.password.hash(password)
    return null
  }
  if (!(await ctx.password.verify({ hash: row.hash, password }))) return null
  basicAttempts.delete(name)
  verifiedBasic.set(name, { password: sha256(password), hash: row.hash })
  return row.user
}

// Asks clients without a session (e.g. OPDS readers) for Basic credentials.
export const unauthorized = () =>
  new Response('Unauthorized', {
    status: 401,
    headers: { 'www-authenticate': 'Basic realm="Bookserve", charset="UTF-8"' },
  })

export const syntheticEmail = (name: string) =>
  `${name.toLowerCase()}@bookserve.local`
import { sql } from 'drizzle-orm'
import {
  index,
  integer,
  real,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core'

import type { MatchedMetadata } from '#/lib/books'

// Better Auth tables (core + `username` and `admin` plugins).
// Keep in sync with the plugins configured in src/lib/auth.ts.

export const user = sqliteTable('user', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  emailVerified: integer('email_verified', { mode: 'boolean' })
    .default(false)
    .notNull(),
  image: text('image'),
  createdAt: integer('created_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull(),
  username: text('username').unique(),
  displayUsername: text('display_username'),
  role: text('role'),
  banned: integer('banned', { mode: 'boolean' }).default(false),
  banReason: text('ban_reason'),
  banExpires: integer('ban_expires', { mode: 'timestamp_ms' }),
})

export const session = sqliteTable(
  'session',
  {
    id: text('id').primaryKey(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    token: text('token').notNull().unique(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    impersonatedBy: text('impersonated_by'),
  },
  (table) => [index('session_user_id_idx').on(table.userId)],
)

export const account = sqliteTable(
  'account',
  {
    id: text('id').primaryKey(),
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: integer('access_token_expires_at', {
      mode: 'timestamp_ms',
    }),
    refreshTokenExpiresAt: integer('refresh_token_expires_at', {
      mode: 'timestamp_ms',
    }),
    scope: text('scope'),
    password: text('password'),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index('account_user_id_idx').on(table.userId)],
)

export const verification = sqliteTable(
  'verification',
  {
    id: text('id').primaryKey(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index('verification_identifier_idx').on(table.identifier)],
)

// Library. A book's columns hold metadata read from its file and are owned by the
// scanner, which overwrites them whenever the file changes. Metadata from other
// sources (Phase 4 matching) goes in `matched` and wins field by field when read
// (see bookView in src/lib/books.ts), so a rescan never clobbers a match.
export const books = sqliteTable(
  'books',
  {
    id: text('id').primaryKey(),
    title: text('title').notNull(),
    sortTitle: text('sort_title').notNull(),
    authors: text('authors', { mode: 'json' })
      .$type<string[]>()
      .default(sql`'[]'`)
      .notNull(),
    description: text('description'),
    language: text('language'),
    publisher: text('publisher'),
    publishedDate: text('published_date'),
    isbn: text('isbn'),
    series: text('series'),
    seriesIndex: real('series_index'),
    // Relative to the data dir, e.g. covers/<id>.jpg.
    coverPath: text('cover_path'),
    matched: text('matched', { mode: 'json' }).$type<MatchedMetadata>(),
    // No file for this book was found by the last complete scan. Rows are kept.
    missing: integer('missing', { mode: 'boolean' }).default(false).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index('books_sort_title_idx').on(table.sortTitle)],
)

export const bookFiles = sqliteTable(
  'book_files',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    bookId: text('book_id')
      .notNull()
      .references(() => books.id, { onDelete: 'cascade' }),
    // Relative to the library dir, with forward slashes.
    path: text('path').notNull().unique(),
    size: integer('size').notNull(),
    mtimeMs: integer('mtime_ms').notNull(),
    // sha256 of the file; finds files that were moved or renamed.
    hash: text('hash').notNull(),
    format: text('format').notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    index('book_files_book_id_idx').on(table.bookId),
    index('book_files_hash_idx').on(table.hash),
  ],
)

// Market sources: an integration (src/lib/market/integrations) plus the
// settings an admin entered for it. The migration that creates this table
// seeds Project Gutenberg.
export const marketSources = sqliteTable('market_sources', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  // Integration id, e.g. `gutenberg` or `opds`.
  integration: text('integration').notNull(),
  name: text('name').notNull(),
  settings: text('settings', { mode: 'json' })
    .$type<Record<string, string>>()
    .default(sql`'{}'`)
    .notNull(),
  createdAt: integer('created_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
})

// Where a book added from the Market came from. `integration` and
// `externalId` are kept when the source is removed.
export const bookSources = sqliteTable(
  'book_sources',
  {
    bookId: text('book_id')
      .primaryKey()
      .references(() => books.id, { onDelete: 'cascade' }),
    sourceId: integer('source_id').references(() => marketSources.id, {
      onDelete: 'set null',
    }),
    integration: text('integration').notNull(),
    // The book's id within the integration.
    externalId: text('external_id').notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
  },
  (table) => [
    index('book_sources_source_external_idx').on(
      table.sourceId,
      table.externalId,
    ),
  ],
)
