import { apiKeyUser } from '#/lib/auth'

// KOSync, the progress sync protocol of KOReader's Progress sync plugin,
// served under /kosync. Behavior follows koreader-sync-server; see
// https://github.com/pid1/kosync-conformance/blob/main/SPEC.md.
// Clients sign in with a Bookserve username and an API key as the password.

// Errors are `{ code, message }`. Clients retry anything but a 401 for weeks,
// so only bad credentials get one.
export const kosyncError = (status: number, code: number, message: string) =>
  Response.json({ code, message }, { status })

export const unauthorized = () => kosyncError(401, 2001, 'Unauthorized')

// Document ids are 32-char hex digests in practice; only ids the GET route can
// serve are stored.
export const isDocumentId = (value: unknown): value is string =>
  typeof value === 'string' && /^[A-Za-z0-9_]{1,64}$/.test(value)

// The user for x-auth-user and x-auth-key (md5 of the API key), or null.
export function kosyncUser(request: Request) {
  const name = request.headers.get('x-auth-user')
  const key = request.headers.get('x-auth-key')
  return name && key ? apiKeyUser(name, key) : null
}

