import { createFileRoute } from '@tanstack/react-router'

import { db } from '#/db'
import { readingProgress } from '#/db/schema'
import {
  isDocumentId,
  kosyncError,
  kosyncUser,
  unauthorized,
} from '#/lib/kosync'

// A reader pushes its position. The last write wins; the client decides
// conflicts from the server's timestamp.
export const Route = createFileRoute('/kosync/syncs/progress/')({
  server: {
    handlers: {
      PUT: async ({ request }) => {
        const user = kosyncUser(request)
        if (!user) return unauthorized()
        const body: Record<string, unknown> | null = await request
          .json()
          .catch(() => null)
        if (!isDocumentId(body?.document)) {
          return kosyncError(403, 2004, "Field 'document' not provided.")
        }
        const percentage = Number(body.percentage)
        const { progress, device } = body
        if (
          body.percentage == null ||
          body.percentage === '' ||
          !Number.isFinite(percentage) ||
          (typeof progress !== 'string' && typeof progress !== 'number') ||
          typeof device !== 'string' ||
          !device
        ) {
          return kosyncError(403, 2003, 'Invalid request')
        }
        const now = new Date(Math.floor(Date.now() / 1000) * 1000)
        const fields = {
          progress: String(progress),
          percentage,
          device,
          deviceId: typeof body.device_id === 'string' ? body.device_id : null,
          updatedAt: now,
        }
        db.insert(readingProgress)
          .values({ userId: user.id, document: body.document, ...fields })
          .onConflictDoUpdate({
            target: [readingProgress.userId, readingProgress.document],
            set: fields,
          })
          .run()
        return Response.json({
          document: body.document,
          timestamp: now.getTime() / 1000,
        })
      },
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'
import { and, eq } from 'drizzle-orm'

import { db } from '#/db'
import { readingProgress } from '#/db/schema'
import {
  isDocumentId,
  kosyncError,
  kosyncUser,
  unauthorized,
} from '#/lib/kosync'

// A reader pulls the last position for a document. An unknown document is
// `200 {}`: the client checks for a missing `percentage`, not the status.
export const Route = createFileRoute('/kosync/syncs/progress/$document')({
  server: {
    handlers: {
      GET: ({ request, params }) => {
        const user = kosyncUser(request)
        if (!user) return unauthorized()
        if (!isDocumentId(params.document)) {
          return kosyncError(403, 2004, "Field 'document' not provided.")
        }
        const row = db
          .select()
          .from(readingProgress)
          .where(
            and(
              eq(readingProgress.userId, user.id),
              eq(readingProgress.document, params.document),
            ),
          )
          .get()
        if (!row) return Response.json({})
        return Response.json({
          document: row.document,
          percentage: row.percentage,
          progress: row.progress,
          device: row.device,
          ...(row.deviceId != null && { device_id: row.deviceId }),
          timestamp: row.updatedAt.getTime() / 1000,
        })
      },
    },
  },
})

